import * as THREE from 'https://unpkg.com/three@0.166.1/build/three.module.js';

const mount=document.querySelector('#game');
const scene=new THREE.Scene();scene.background=new THREE.Color('#a5b5a4');scene.fog=new THREE.Fog('#a5b5a4',28,62);
const camera=new THREE.PerspectiveCamera(42,innerWidth/innerHeight,.1,100);camera.position.set(0,20,24);
const renderer=new THREE.WebGLRenderer({antialias:true,alpha:false});renderer.setPixelRatio(Math.min(devicePixelRatio,1.8));renderer.setSize(innerWidth,innerHeight);renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.12;mount.appendChild(renderer.domElement);
scene.add(new THREE.HemisphereLight('#e5f1d8','#364b47',2.1));const sun=new THREE.DirectionalLight('#fff0ce',3.3);sun.position.set(-11,20,10);sun.castShadow=true;sun.shadow.mapSize.set(1024,1024);sun.shadow.camera.left=-22;sun.shadow.camera.right=22;sun.shadow.camera.top=22;sun.shadow.camera.bottom=-22;scene.add(sun);
const mat=(color,roughness=.85)=>new THREE.MeshStandardMaterial({color,roughness});
const M={grass:mat('#718c6d'),path:mat('#b4ab8d'),darkPath:mat('#8d8a73'),hedge:mat('#3f674e'),hedge2:mat('#527857'),wall:mat('#d1c9ac'),wallTop:mat('#e2d9be'),roof:mat('#5f7065'),wood:mat('#725844'),metal:mat('#586b69'),gold:mat('#e6b64e'),red:mat('#bb443d'),black:mat('#202d31'),skin:mat('#c9a67c'),blue:mat('#718e93'),white:mat('#e5e3d8')};
function box(name,x,y,z,sx,sy,sz,material,cast=true,receive=true){const o=new THREE.Mesh(new THREE.BoxGeometry(sx,sy,sz),material);o.name=name;o.position.set(x,y,z);o.castShadow=cast;o.receiveShadow=receive;scene.add(o);return o}
function cylinder(x,y,z,r1,r2,h,material,segments=12){const o=new THREE.Mesh(new THREE.CylinderGeometry(r1,r2,h,segments),material);o.position.set(x,y,z);o.castShadow=true;o.receiveShadow=true;scene.add(o);return o}
// Grounds and geometric garden paths
box('ground',0,-.22,0,34,.4,30,M.grass,false,true);
box('north path',0,-.005,-7,34,.04,2.4,M.path,false);
box('east path',9,-.002,0,2.2,.045,17,M.path,false);
box('cross path',-1,-.002,1,16,.04,1.8,M.path,false);
box('entry path',-10,-.001,8,2,.045,10,M.path,false);
// perimeter and compound architecture
box('north wall',0,.75,-14.5,34,1.5,.55,M.wall);box('south wall',0,.75,14.5,34,1.5,.55,M.wall);box('west wall',-16.5,.75,0,.55,1.5,29,M.wall);box('east wall',16.5,.75,0,.55,1.5,29,M.wall);
for(let x=-15.3;x<16;x+=2.2){box('wall cap',x,1.58,-14.5,1.65,.18,.7,M.wallTop);box('wall cap',x,1.58,14.5,1.65,.18,.7,M.wallTop)}
// gate opening and exit beacon
box('gate left',-11,1.2,14.5,2.5,2.4,.55,M.wall);box('gate right',-5.8,1.2,14.5,2.5,2.4,.55,M.wall);box('gate lintel',-8.4,2.45,14.5,2.7,.45,.65,M.wallTop);
const exitGlow=new THREE.Mesh(new THREE.TorusGeometry(1.05,.08,8,32),new THREE.MeshBasicMaterial({color:'#d5f16a'}));exitGlow.rotation.x=Math.PI/2;exitGlow.position.set(-8.4,.18,12.6);scene.add(exitGlow);
const exitDisk=new THREE.Mesh(new THREE.CircleGeometry(1.12,32),new THREE.MeshBasicMaterial({color:'#d5f16a',transparent:true,opacity:.13,side:THREE.DoubleSide}));exitDisk.rotation.x=-Math.PI/2;exitDisk.position.set(-8.4,.03,12.6);scene.add(exitDisk);
// Modern villa and entry terrace
box('villa foundation',3,.18,-10,11,.36,5.5,M.darkPath);box('villa',3,1.65,-10,9,3,4.2,M.wall);box('villa roof',3,3.35,-10,10,.38,5.1,M.roof);
for(const x of [-.4,2.2,4.8,7.4]){box('window',x,1.75,-7.86,1.1,1.5,.07,M.metal);box('window frame',x,1.75,-7.8,1.2,.07,.08,M.wallTop)}
box('villa porch',3,.12,-6.8,7,.25,1.8,M.path);for(const x of [0,6])cylinder(x,1,-6.8,.12,.16,1.8,M.wallTop,10);
// perimeter topiary and low cover beds
function hedge(x,z,sx,sz){box('hedge',x,.58,z,sx,1.15,sz,M.hedge);box('hedge highlight',x,.98,z,sx,.36,sz,M.hedge2)}
hedge(-12,-5,5,.9);hedge(-6,-5,2.5,.9);hedge(11,-4,1,6);hedge(12,5,5,.9);hedge(4,4,4.5,.9);hedge(-2,8,6,.9);hedge(3,0,.8,4);hedge(-12,3,.8,4);
// ornamental trees
function tree(x,z,r=1){cylinder(x,.8,z,.18,.25,1.6,M.wood,8);const crown=new THREE.Mesh(new THREE.IcosahedronGeometry(r,1),mat('#3f684e'));crown.position.set(x,2.15,z);crown.castShadow=true;scene.add(crown);const crown2=new THREE.Mesh(new THREE.IcosahedronGeometry(r*.67,1),mat('#527958'));crown2.position.set(x-.2,2.7,z+.12);crown2.castShadow=true;scene.add(crown2)}
for(const [x,z,r] of [[-14,-10,1.3],[-13,10,1.4],[14,10,1.2],[14,-10,1.4],[-8,-10,1],[9,9,1.2],[-7,4,.9]])tree(x,z,r);
// Lamps
for(const [x,z] of [[-9,-6],[8,-6],[8,7],[-10,7]]){cylinder(x,.9,z,.09,.13,1.8,M.metal,10);const orb=new THREE.Mesh(new THREE.SphereGeometry(.19,12,8),new THREE.MeshBasicMaterial({color:'#e4dbac'}));orb.position.set(x,1.83,z);scene.add(orb)}
// intel terminal / dossier pedestal
box('intel plinth',1.2,.34,-1.7,1.35,.68,1.05,M.metal);box('intel top',1.2,.72,-1.7,1.48,.12,1.16,M.gold);
const dossier=new THREE.Group();const caseBody=new THREE.Mesh(new THREE.BoxGeometry(.78,.2,.56),mat('#b1843f'));caseBody.position.y=.95;caseBody.castShadow=true;dossier.add(caseBody);const caseLine=new THREE.Mesh(new THREE.BoxGeometry(.8,.045,.58),mat('#f0d17d'));caseLine.position.y=1.065;dossier.add(caseLine);dossier.position.set(1.2,0,-1.7);scene.add(dossier);
// Add small flower accents to grounds
const flowerMat=[mat('#d6c58e'),mat('#c48670')];for(let i=0;i<32;i++){const x=((i*37)%290)/10-14.5,z=((i*61)%250)/10-12.5;if(Math.abs(x)<4&&z<-7)continue;const f=new THREE.Mesh(new THREE.SphereGeometry(.09,7,5),flowerMat[i%2]);f.position.set(x,.055,z);scene.add(f)}

// Agent and patrol construction
function makeAgent({player=false}){const root=new THREE.Group();scene.add(root);const body=new THREE.Mesh(new THREE.CylinderGeometry(.3,.37,.92,10),player?mat('#252e32'):mat('#657c7a'));body.position.y=.69;body.castShadow=true;root.add(body);const head=new THREE.Mesh(new THREE.SphereGeometry(.24,12,10),player?mat('#c5a17c'):mat('#b89b78'));head.position.y=1.35;head.castShadow=true;root.add(head);const cap=new THREE.Mesh(new THREE.SphereGeometry(.255,12,7,0,Math.PI*2,0,Math.PI/2),player?mat('#202729'):mat('#3c5553'));cap.position.y=1.38;root.add(cap);const pack=new THREE.Mesh(new THREE.BoxGeometry(.4,.52,.2),player?mat('#364144'):mat('#526b68'));pack.position.set(0,.82,-.29);pack.castShadow=true;root.add(pack);const legs=[];for(const side of [-1,1]){const leg=new THREE.Mesh(new THREE.CylinderGeometry(.095,.12,.55,8),player?mat('#323a3b'):mat('#465856'));leg.position.set(side*.16,.28,0);leg.castShadow=true;root.add(leg);legs.push(leg)}return {root,body,head,legs}}
const player=makeAgent({player:true});player.root.position.set(-8,0,10.8);
const coverZones=[[-12,-5,2.5,.75],[-6,-5,1.25,.75],[11,-4,.75,2.7],[12,5,2.7,.75],[4,4,2.2,.75],[-2,8,3,.75],[3,0,.65,1.8],[-12,3,.65,1.8],[3,-10,5.1,2.15]];
const guards=[];
function makeGuard(path,phase=0){const actor=makeAgent();actor.root.scale.setScalar(.92);const coneGeo=new THREE.BufferGeometry();const vertices=[0,.055,0];const steps=28,range=5.8,half=.67;for(let i=0;i<=steps;i++){const a=-half+2*half*i/steps;vertices.push(Math.sin(a)*range,.055,Math.cos(a)*range)}const indices=[];for(let i=0;i<steps;i++)indices.push(0,i+1,i+2);coneGeo.setAttribute('position',new THREE.Float32BufferAttribute(vertices,3));coneGeo.setIndex(indices);coneGeo.computeVertexNormals();const cone=new THREE.Mesh(coneGeo,new THREE.MeshBasicMaterial({color:'#e4b75d',transparent:true,opacity:.18,depthWrite:false,side:THREE.DoubleSide}));cone.renderOrder=1;actor.root.add(cone);const guard={...actor,path,index:0,phase,cone,dir:new THREE.Vector3(0,0,1),down:false,alerted:false};guard.root.position.set(path[0][0],0,path[0][1]);guards.push(guard);return guard}
makeGuard([[-4,-3],[4,-3],[4,1],[-4,1]],0);makeGuard([[9,-1],[9,7],[6,7],[6,2]],1.8);makeGuard([[-11,1],[-7,1],[-7,7],[-11,7]],3.1);
// Collision and vision helpers
const blockers=[...coverZones.map(([x,z,hx,hz])=>({x,z,hx,hz})),{x:3,z:-10,hx:5.1,hz:2.55}];
function isBlocked(x,z){if(Math.abs(x)>15.65||Math.abs(z)>13.65)return true;for(const b of blockers)if(Math.abs(x-b.x)<b.hx+.38&&Math.abs(z-b.z)<b.hz+.38)return true;return false}
function hasCover(ax,az,bx,bz){const steps=Math.ceil(Math.hypot(bx-ax,bz-az)/.28);for(let i=1;i<steps;i++){const t=i/steps,x=ax+(bx-ax)*t,z=az+(bz-az)*t;for(const b of blockers)if(Math.abs(x-b.x)<b.hx&&Math.abs(z-b.z)<b.hz)return true}return false}
const state={started:false,intel:false,done:false,failed:false,sneak:false,alarm:0,spotted:0,nearby:null};let time=0;let alertTimer=0;
const el=(s)=>document.querySelector(s),actionBtn=el('#action'),stick=el('#stick'),knob=el('#knob');
function notify(title,text){el('#toastTitle').textContent=title;el('#toastText').textContent=text;el('#toast').classList.add('show');setTimeout(()=>el('#toast').classList.remove('show'),2100)}
function showAlert(){el('#alert').classList.add('on');alertTimer=1.2}
function refreshHud(){el('#topGoal').textContent=state.intel?'REACH THE EXTRACTION':'ACQUIRE THE INTEL';el('#cardTitle').textContent=state.intel?'Reach the extraction':'Secure the dossier';el('#cardText').textContent=state.intel?'Exit through the south gate. Keep moving and stay unseen.':'Find the marked intel case. Stay out of the guards’ sight.';el('#progress').style.width=state.intel?'100%':'0%';el('#statusText').innerHTML=state.failed?'OPERATION <b style="color:#ff665d">COMPROMISED</b>':state.done?'OPERATION <b>COMPLETE</b>':state.alarm>0?'ALERT <b style="color:#ff665d">'+Math.round(state.alarm)+'%</b>':'OPERATION <b>LIVE</b>';el('#statusDot').style.background=state.alarm>30?'#ff665d':'#d5f16a';el('#statusDot').style.boxShadow=state.alarm>30?'0 0 12px #ff665d':'0 0 12px #d5f16a';if(state.nearby?.type==='guard'){actionBtn.textContent='SUBDUE'}else if(state.nearby?.type==='intel')actionBtn.textContent='SECURE';else if(state.nearby?.type==='exit')actionBtn.textContent='EXTRACT';else actionBtn.textContent='INTERACT'}
function nearestAction(){let best=null,dist=Infinity;const p=player.root.position;if(!state.intel&&dossier.visible){const d=Math.hypot(p.x-1.2,p.z+1.7);if(d<2.1&&d<dist){best={type:'intel'};dist=d}}if(state.intel){const d=Math.hypot(p.x+8.4,p.z-12.6);if(d<2.2&&d<dist){best={type:'exit'};dist=d}}for(const g of guards){if(g.down)continue;const d=Math.hypot(p.x-g.root.position.x,p.z-g.root.position.z);if(d<1.6&&d<dist){best={type:'guard',guard:g};dist=d}}state.nearby=best;refreshHud()}
function interact(){if(!state.started||state.done||state.failed)return;nearestAction();if(!state.nearby){notify('NOT IN RANGE','Move closer to an objective.');return}if(state.nearby.type==='guard'){const g=state.nearby.guard;g.down=true;g.root.visible=false;state.alarm=Math.max(0,state.alarm-12);notify('GUARD SUBDUED','Quietly. Keep moving.');state.nearby=null}else if(state.nearby.type==='intel'){state.intel=true;dossier.visible=false;notify('INTEL SECURED','Now reach the extraction point.');state.nearby=null;refreshHud()}else{state.done=true;state.started=false;showEnd(true)}}
actionBtn.addEventListener('pointerdown',e=>{e.preventDefault();interact()});
function showEnd(win){const panel=document.querySelector('.intro');panel.innerHTML=win?'<div class="kicker">MISSION REPORT // CLEARED</div><h1>GHOST<br><span>PROTOCOL</span><br>COMPLETE</h1><div class="sub">CLEAN ENTRY. CLEAN EXIT.</div><div class="divider"></div><div class="brief">The dossier is safe. The compound is quiet. <b>That’s how professionals leave.</b></div><div class="divider"></div><button class="start" id="again">RUN IT AGAIN&nbsp; →</button><div class="note">MISSION TIME&nbsp; '+formatTime(time)+'</div>':'<div class="kicker">MISSION REPORT // FAILED</div><h1>YOU’VE<br><span>BEEN</span><br>MADE</h1><div class="sub">THE COMPOUND IS ON LOCKDOWN.</div><div class="divider"></div><div class="brief">The guards identified you. A clean operator knows when to disappear. <b>Try another approach.</b></div><div class="divider"></div><button class="start" id="again">RETRY OPERATION&nbsp; →</button><div class="note">MOVE SLOWLY · USE COVER · WATCH PATROLS</div>';el('#overlay').classList.remove('hidden');el('#hud').classList.add('hidden');document.querySelector('#again').addEventListener('click',()=>location.reload())}
// Touch joystick and keyboard input
let stickPointer=null,moveX=0,moveY=0;function setStick(e){const r=stick.getBoundingClientRect(),dx=e.clientX-(r.left+r.width/2),dy=e.clientY-(r.top+r.height/2),max=r.width*.34,d=Math.hypot(dx,dy),k=Math.min(1,max/(d||1));moveX=dx*k/max;moveY=dy*k/max;knob.style.left=`${50+moveX*34}%`;knob.style.top=`${50+moveY*34}%`}
stick.addEventListener('pointerdown',e=>{e.preventDefault();stickPointer=e.pointerId;stick.setPointerCapture(e.pointerId);setStick(e)});stick.addEventListener('pointermove',e=>{if(e.pointerId===stickPointer)setStick(e)});function releaseStick(e){if(e.pointerId!==stickPointer)return;stickPointer=null;moveX=moveY=0;knob.style.left='50%';knob.style.top='50%'}stick.addEventListener('pointerup',releaseStick);stick.addEventListener('pointercancel',releaseStick);
const keys={};window.addEventListener('keydown',e=>{keys[e.key.toLowerCase()]=true;if(e.key===' '){e.preventDefault();interact()}if(e.key.toLowerCase()==='shift')toggleSneak(true)});window.addEventListener('keyup',e=>{keys[e.key.toLowerCase()]=false;if(e.key.toLowerCase()==='shift')toggleSneak(false)});
function toggleSneak(force){state.sneak=typeof force==='boolean'?force:!state.sneak;el('#sneak').classList.toggle('active',state.sneak);el('#sneakCaption').textContent=state.sneak?'SNEAK ON':'SNEAK OFF'}el('#sneak').addEventListener('pointerdown',e=>{e.preventDefault();toggleSneak()});

// Runtime loop, stealth detection, and responsive camera
const clock=new THREE.Clock();const camTarget=new THREE.Vector3();let lastHud=0;let moveAmount=0;
function formatTime(seconds){const total=Math.floor(seconds),m=String(Math.floor(total/60)).padStart(2,'0'),s=String(total%60).padStart(2,'0');return `${m}:${s}`}
function finish(){if(state.done||state.failed)return;state.failed=true;state.started=false;showEnd(false)}
function update(dt){time+=dt;const p=player.root.position;let ix=moveX,iz=moveY;if(keys.w||keys.arrowup)iz-=1;if(keys.s||keys.arrowdown)iz+=1;if(keys.a||keys.arrowleft)ix-=1;if(keys.d||keys.arrowright)ix+=1;const len=Math.hypot(ix,iz);if(len>1){ix/=len;iz/=len}moveAmount=Math.min(1,Math.hypot(ix,iz));const speed=state.sneak?2.05:3.75;if(state.started&&!state.done&&!state.failed&&moveAmount>.04){const nx=p.x+ix*speed*dt, nz=p.z+iz*speed*dt;if(!isBlocked(nx,p.z))p.x=nx;if(!isBlocked(p.x,nz))p.z=nz;player.root.rotation.y=Math.atan2(ix,iz);player.body.position.y=.69+Math.sin(time*10)*.035*moveAmount;player.legs[0].rotation.x=Math.sin(time*10)*.24*moveAmount;player.legs[1].rotation.x=-Math.sin(time*10)*.24*moveAmount}else{player.body.position.y=.69;player.legs[0].rotation.x=player.legs[1].rotation.x=0}
  for(const g of guards){if(g.down)continue;const gp=g.root.position;let target=g.path[g.index];let dx=target[0]-gp.x,dz=target[1]-gp.z,d=Math.hypot(dx,dz);if(d<.22){g.index=(g.index+1)%g.path.length;target=g.path[g.index];dx=target[0]-gp.x;dz=target[1]-gp.z;d=Math.hypot(dx,dz)}let chasing=false;if(g.alerted&&Math.hypot(p.x-gp.x,p.z-gp.z)<9&&!hasCover(gp.x,gp.z,p.x,p.z)){target=[p.x,p.z];dx=target[0]-gp.x;dz=target[1]-gp.z;d=Math.hypot(dx,dz);chasing=true}else g.alerted=false;if(d>.001){g.dir.set(dx/d,0,dz/d);g.root.rotation.y=Math.atan2(g.dir.x,g.dir.z);if(!chasing){gp.x+=g.dir.x*1.04*dt;gp.z+=g.dir.z*1.04*dt}else{gp.x+=g.dir.x*1.65*dt;gp.z+=g.dir.z*1.65*dt}}const dist=Math.hypot(p.x-gp.x,p.z-gp.z);const toward=((p.x-gp.x)*g.dir.x+(p.z-gp.z)*g.dir.z)/(dist||1);const sees=dist<(state.sneak?4.1:6.5)&&toward>(state.sneak?.72:.52)&&!hasCover(gp.x,gp.z,p.x,p.z);if(sees){g.alerted=true;state.spotted++;state.alarm=Math.min(100,state.alarm+32*dt);if(state.spotted<2)showAlert()}else{state.alarm=Math.max(0,state.alarm-10*dt);state.spotted=Math.max(0,state.spotted-2*dt)}g.cone.material.color.set(g.alerted?'#f05c50':'#e4b75d');g.cone.material.opacity=g.alerted?.27:.16}
  if(state.alarm>=100)finish();if(alertTimer>0){alertTimer-=dt;if(alertTimer<=0)el('#alert').classList.remove('on')}if(!state.done&&!state.failed){if(time-lastHud>.18){nearestAction();lastHud=time}}dossier.rotation.y=Math.sin(time*1.1)*.12;dossier.position.y=Math.sin(time*2.2)*.07;exitGlow.rotation.z=time*.55;exitDisk.material.opacity=.1+Math.sin(time*2)*.04;
}
function render(){const dt=Math.min(clock.getDelta(),.04);if(state.started)update(dt);const p=player.root.position;camTarget.set(p.x,0,p.z);const distance=innerWidth<700?25.5:29;const desired=new THREE.Vector3(p.x,p.y+distance*.72,p.z+distance*.86);camera.position.lerp(desired,.075);camera.lookAt(p.x,0,p.z-1.6);renderer.render(scene,camera);requestAnimationFrame(render)}
function resize(){camera.aspect=innerWidth/innerHeight;camera.fov=innerWidth<600?44:42;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);renderer.setPixelRatio(Math.min(devicePixelRatio,1.8))}window.addEventListener('resize',resize);
el('#start').addEventListener('click',()=>{el('#overlay').classList.add('hidden');el('#hud').classList.remove('hidden');state.started=true;renderer.domElement.focus()});
// Put game in a ready state behind the briefing screen
el('#hud').classList.add('hidden');refreshHud();render();

